style.css:
@-moz-document domain("developer.android.com") {
:root {
    --bg-color: #161f31;
    --bg-dark-color: #121928;
    --fg-color: #c9d8ee;
    --fg-dark-color: #a9bad6;
    --red-color: #ff3939;
    --orange-color: #ff9f39;
    --yellow-color: #ffea39;
    --purple-color: #d62ed6;
    --cyan-color: #42caca;
    --green-color: #64f923;
    --blue-color: #5889ff;
    --pink-color: #f36cde;
    --border-color: #e1e1e1;
    --none: none;
  }

  div,
  dl,
  dt,
  dd,
  ul,
  ol,
  li,
  pre,
  label,
  fieldset,
  input,
  p,
  blockquote,
  th,
  td,
  i,
  i::before,
  font,
  body {
    color: var(--fg-color) !important;
  }

  main,
  body {
    background: var(--bg-color);
  }

    h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: white !important;
  }

  ins {
    color: var(--green-color) !important;
    background: none !important;
  }

  del {
    color: var(--red-color) !important;
    background: none !important;
  }

  a {
    color: var(--pink-color);
  }

  a:link {
    color: var(--cyan-color);
  }

  a:hover {
    filter: brightness(0.8);
    background: none !important;
  }

  img {
    filter: invert(100%) brightness(95%) !important;
  }

  pre[class^="language"],
  code {
    background: var(--bg-dark-color) !important;
    color: var(--fg-dark-color) !important;
  }



  table {
    border-collapse: collapse !important;
  }

  table,
  noscript,
  select,
  input,
  tr,
  td,
  th,
  option {
    border: 1px solid var(--border-color) !important;
    background: var(--bg-dark-color) !important;
    color: var(--red-color) !important;
  }
  blockquote {
    background: var(--bg-dark-color) !important;
    border: 1px solid var(--border-color) !important;
    color: var(--fg-dark-color) !important;
  }

#codelab-title ,
 .inner {
  background: var(--bg-color) !important;
   color: var(--fg-color) !important;
}


ol {
	    background: var(--bg-dark-color) !important;

}
.metadata {
background: var(--bg-dark-color) !important;
   color: var(--green-color) !important;
}

ol  a {
		background: var(--bg-dark-color) !important;
   color: var(--fg-color) !important;
}

google-codelab-step{
  background: var(--bg-dark-color) !important;
   color: var(--fg-color) !important;
}

.step-title > a {
	color: var(--blue-color) !important;
}
.title > a {
		color: var(--blue-color) !important;
}
devsite-language-selector {
background: var(--bg-dark-color) !important;
   color: var(--fg-color) !important;
}

.special {
 background: var(--bg-dark-color) !important;
  }
.about-card {
	 background: var(--bg-dark-color) !important;
}
  .warning {
		 background: var(--bg-dark-color) !important;
		color: var(--yellow-color) !important;
}
}
